<?php
namespace App\Http\Controllers;
use App\Models\{Product,Category,Brand,AttributeValue}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Storage; use Illuminate\Support\Str;
class ProductController extends Controller {
 public function index(Request $r){$q=$r->string('q')->toString();$products=Product::with(['category','brand','skus'])->when($q,fn($x)=>$x->where(fn($y)=>$y->where('name','like',"%$q%")->orWhere('slug','like',"%$q%")))->latest('product_id')->paginate(15)->withQueryString();return view('admin.products.index',compact('products','q'));}
 public function create(){return view('admin.products.form',['product'=>new Product,'categories'=>Category::orderBy('name')->get(),'brands'=>Brand::orderBy('name')->get(),'attributeValues'=>AttributeValue::with('attribute')->orderBy('attribute_id')->get(),'sku'=>null]);}
 public function store(Request $r){$d=$r->validate(['category_id'=>'required|exists:categories,category_id','brand_id'=>'nullable|exists:brands,brand_id','name'=>'required|string|max:150','slug'=>'nullable|string|max:200|unique:products,slug','description'=>'nullable|string','is_active'=>'nullable|boolean','sku_code'=>'required|string|max:100|unique:product_skus,sku_code','price'=>'required|numeric|min:0','stock_quantity'=>'required|integer|min:0','image'=>'nullable|image|max:4096','attribute_values'=>'nullable|array','attribute_values.*'=>'exists:attribute_values,value_id']);DB::transaction(function()use($r,$d,&$product){$product=Product::create(['category_id'=>$d['category_id'],'brand_id'=>$d['brand_id']??null,'name'=>$d['name'],'slug'=>$d['slug']?:Str::slug($d['name']), 'description'=>$d['description']??null,'is_active'=>$r->boolean('is_active')]);$image=null;if($r->hasFile('image'))$image=$r->file('image')->store('products','public');$sku=$product->skus()->create(['sku_code'=>$d['sku_code'],'price'=>$d['price'],'stock_quantity'=>$d['stock_quantity'],'image_url'=>$image]);$sku->attributeValues()->sync($d['attribute_values']??[]);});return redirect()->route('admin.products.index')->with('success','Product created successfully.');}
 public function edit(Product $product){$product->load('skus.attributeValues');return view('admin.products.form',['product'=>$product,'categories'=>Category::orderBy('name')->get(),'brands'=>Brand::orderBy('name')->get(),'attributeValues'=>AttributeValue::with('attribute')->orderBy('attribute_id')->get(),'sku'=>$product->skus->first()]);}
 public function update(Request $r,Product $product){$sku=$product->skus()->firstOrFail();$d=$r->validate(['category_id'=>'required|exists:categories,category_id','brand_id'=>'nullable|exists:brands,brand_id','name'=>'required|string|max:150','slug'=>'nullable|string|max:200|unique:products,slug,'.$product->product_id.',product_id','description'=>'nullable|string','is_active'=>'nullable|boolean','sku_code'=>'required|string|max:100|unique:product_skus,sku_code,'.$sku->sku_id.',sku_id','price'=>'required|numeric|min:0','stock_quantity'=>'required|integer|min:0','image'=>'nullable|image|max:4096','attribute_values'=>'nullable|array','attribute_values.*'=>'exists:attribute_values,value_id']);DB::transaction(function()use($r,$d,$product,$sku){$product->update(['category_id'=>$d['category_id'],'brand_id'=>$d['brand_id']??null,'name'=>$d['name'],'slug'=>$d['slug']?:Str::slug($d['name']),'description'=>$d['description']??null,'is_active'=>$r->boolean('is_active')]);$image=$sku->image_url;if($r->hasFile('image')){$image=$r->file('image')->store('products','public');}$sku->update(['sku_code'=>$d['sku_code'],'price'=>$d['price'],'stock_quantity'=>$d['stock_quantity'],'image_url'=>$image]);$sku->attributeValues()->sync($d['attribute_values']??[]);});return redirect()->route('admin.products.index')->with('success','Product updated.');}
 public function destroy(Product $product){$product->delete();return back()->with('success','Product deleted.');}
 public function show(Product $product){$product->load(['category','brand','skus.attributeValues','reviews.user']);return view('admin.products.show',compact('product'));}
}
